import { createFileRoute } from "@tanstack/react-router";
import { apiFetch } from "@/lib/api";

// The sitemap is generated by the backend from MongoDB (all published posts and
// projects); serve it from the site's own origin so search engines accept it.
export const Route = createFileRoute("/sitemap.xml")({
  server: {
    handlers: {
      GET: async () => {
        try {
          const res = await apiFetch("/sitemap.xml", { timeoutMs: 30_000 });
          if (!res.ok) return new Response("Sitemap unavailable", { status: 502 });
          return new Response(await res.text(), {
            headers: {
              "Content-Type": "application/xml; charset=utf-8",
              "Cache-Control": "public, max-age=0, s-maxage=3600, stale-while-revalidate=86400",
            },
          });
        } catch {
          return new Response("Sitemap unavailable", { status: 502 });
        }
      },
    },
  },
});
